 3	export interface AvailabilitySlot {
 4	  startsAt: string;
 5	  endsAt: string;
 6	}
 7	
 8	function toIso(timestamp: number): string {
 9	  return new Date(timestamp).toISOString().replace(".000Z", "Z");
10	}
11	
12	function nextUtcDay(date: string): string {
13	  const start = Date.parse(`${date}T00:00:00Z`);
14	  return toIso(start + 24 * 60 * 60 * 1000);
15	}
16	
17	export function dayBounds(date: string): AvailabilitySlot {
18	  return {
19	    startsAt: `${date}T00:00:00Z`,
20	    endsAt: nextUtcDay(date)
21	  };
22	}
23	
24	export function isIsoDay(value: unknown): value is string {
25	  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
26	    return false;
27	  }
28	  const parsed = Date.parse(`${value}T00:00:00Z`);
29	  return !Number.isNaN(parsed) && toIso(parsed).startsWith(value);
30	}
