32	export function availabilityForDay(bookings: Booking[], date: string): AvailabilitySlot[] {
33	  const day = dayBounds(date);
34	  const dayStart = Date.parse(day.startsAt);
35	  const dayEnd = Date.parse(day.endsAt);
36	  const busySlots = bookings
37	    .map((booking) => ({
38	      startsAt: Math.max(Date.parse(booking.startsAt), dayStart),
39	      endsAt: Math.min(Date.parse(booking.endsAt), dayEnd)
40	    }))
41	    .filter((slot) => slot.startsAt < slot.endsAt)
42	    .sort((a, b) => a.startsAt - b.startsAt);
43	
44	  const freeSlots: AvailabilitySlot[] = [];
45	  let cursor = dayStart;
46	
47	  for (const busy of busySlots) {
48	    if (cursor < busy.startsAt) {
49	      freeSlots.push({ startsAt: toIso(cursor), endsAt: toIso(busy.startsAt) });
50	    }
51	    cursor = Math.max(cursor, busy.endsAt);
52	  }
53	
54	  if (cursor < dayEnd) {
55	    freeSlots.push({ startsAt: toIso(cursor), endsAt: toIso(dayEnd) });
56	  }
57	
58	  return freeSlots;
59	}
