 2	import { Readable, Writable } from "node:stream";
 3	import { createApp } from "../src/app.js";
 4	
 5	interface JsonResponse {
 6	  status: number;
 7	  body: {
 8	    slots?: unknown;
 9	    [key: string]: unknown;
10	  };
11	}
12	
13	async function call(path: string) {
14	  const app = createApp();
15	  const req = Object.assign(
16	    new Readable({
17	      read() {
18	        this.push(null);
19	      }
20	    }),
21	    {
22	      method: "GET",
23	      url: path,
24	      headers: {}
25	    }
26	  );
27	  const chunks: Buffer[] = [];
28	  const headers: Record<string, unknown> = {};
29	
30	  return await new Promise<JsonResponse>((resolve, reject) => {
31	    const res = Object.assign(new Writable(), {
32	      statusCode: 200,
33	      setHeader(name: string, value: unknown) {
34	        headers[name.toLowerCase()] = value;
35	      },
36	      getHeader(name: string) {
37	        return headers[name.toLowerCase()];
38	      },
39	      removeHeader(name: string) {
40	        delete headers[name.toLowerCase()];
41	      },
42	      end(chunk?: string | Buffer, _encoding?: BufferEncoding, callback?: () => void) {
43	        if (chunk) {
44	          chunks.push(Buffer.from(chunk));
45	        }
46	        callback?.();
47	        resolve({
48	          status: res.statusCode,
49	          body: JSON.parse(Buffer.concat(chunks).toString())
50	        });
51	        return res;
52	      }
53	    });
54	
55	    app(req as never, res as never, reject);
56	  });
57	}
